const http = require('node:http');
function primos(n) { let c = 0; for (let i = 2; i < n; i++) { let ok = true; for (let d = 2; d * d <= i; d++) if (i % d === 0) { ok = false; break; } if (ok) c++; } return c; }
http.createServer((req, res) => {
  if (req.url === '/espera') return setTimeout(() => res.end('ok'), 20);
  if (req.url === '/calculo') return res.end(String(primos(20000)));
  res.end('hola');
}).listen(19727, '127.0.0.1');

// Matriz de decisión con un caso INVENTADO. Los puntajes (1 a 5) son opinión, no datos medidos.
const criterios = ['equipo hoy', 'contratar', 'madurez', 'costo oculto', 'primera versión', 'rendimiento'];
const pesos = [30, 15, 15, 20, 15, 5];
// Puntajes de las columnas que no dependen del equipo
const comun = {
  'Node + TypeScript':  { contratar: 4, madurez: 4, costo: 4, rend: 3 },
  'Python + FastAPI':   { contratar: 4, madurez: 4, costo: 4, rend: 2 },
  'Java + Spring Boot': { contratar: 4, madurez: 5, costo: 3, rend: 4 },
  'Go':                 { contratar: 2, madurez: 4, costo: 4, rend: 5 },
};
// Lo que sabe el equipo: la única columna que cambia entre los dos casos
const equipos = {
  'Equipo A (sabe JS/TS)':  { 'Node + TypeScript': [5, 5], 'Python + FastAPI': [3, 4], 'Java + Spring Boot': [1, 2], 'Go': [1, 3] },
  'Equipo B (sabe Java)':   { 'Node + TypeScript': [2, 3], 'Python + FastAPI': [2, 3], 'Java + Spring Boot': [5, 5], 'Go': [1, 3] },
};
function puntajes(eq) {
  return Object.fromEntries(Object.entries(comun).map(([n, c]) =>
    [n, [eq[n][0], c.contratar, c.madurez, c.costo, eq[n][1], c.rend]]));
}
function total(p, w) { const s = w.reduce((a, b) => a + b, 0); return p.reduce((acc, v, i) => acc + v * w[i], 0) / s; }
function ranking(tabla, w) { return Object.entries(tabla).map(([n, p]) => [n, total(p, w)]).sort((a, b) => b[1] - a[1]); }

for (const [nombre, eq] of Object.entries(equipos)) {
  const r = ranking(puntajes(eq), pesos);
  console.log(`\n${nombre}, pesos ${pesos.join('/')}`);
  r.forEach(([n, t], i) => console.log(`  ${i + 1}. ${n.padEnd(20)} ${t.toFixed(2)}`));
}

// ¿Cuánto tendría que pesar el rendimiento para que Go le gane a Node en el equipo A?
const tablaA = puntajes(equipos['Equipo A (sabe JS/TS)']);
for (let rend = 5; rend <= 100; rend += 1) {
  const resto = pesos.slice(0, 5), suma = resto.reduce((a, b) => a + b, 0);
  const w = [...resto.map(x => x * (100 - rend) / suma), rend];
  const r = ranking(tablaA, w);
  if (r[0][0] === 'Go') { console.log(`\nEquipo A: Go supera a Node cuando el rendimiento pesa ${rend} % (hoy pesa 5 %)`); break; }
}
